import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Resume from './components/Resume';
import Projects from './components/Projects';
import Links from './components/Links';
import Footer from './components/Footer';
import { fetchProfile, fetchProjects, fetchResume, fetchLinks } from './supabaseClient';

// Fallback data when Supabase is not connected
const fallbackData = {
  profile: {
    name: 'Faiq',
    title: 'Full Stack Developer',
    bio: 'Passionate developer crafting digital experiences that matter. I build modern web applications with clean code and creative solutions.',
    avatar_url: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Faiq',
    email: 'faiq@example.com',
    location: 'Malaysia'
  },
  projects: [
    {
      id: 1,
      title: 'E-Commerce Platform',
      description: 'A full-featured online store with cart, payments, and admin dashboard.',
      image_url: 'https://images.unsplash.com/photo-1557821552-17105176677c?w=600',
      tech_stack: ['React', 'Node.js', 'PostgreSQL'],
      live_url: 'https://example.com',
      github_url: 'https://github.com',
      featured: true
    },
    {
      id: 2,
      title: 'Task Management App',
      description: 'Collaborative task manager with real-time updates and team features.',
      image_url: 'https://images.unsplash.com/photo-1611224923853-80b023f02d71?w=600',
      tech_stack: ['React', 'Firebase', 'Tailwind'],
      live_url: 'https://example.com',
      github_url: 'https://github.com',
      featured: true
    },
    {
      id: 3,
      title: 'Portfolio Website',
      description: 'Personal portfolio showcasing projects and skills with modern design.',
      image_url: 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=600',
      tech_stack: ['React', 'Supabase', 'Framer Motion'],
      live_url: 'https://example.com',
      github_url: 'https://github.com',
      featured: false
    }
  ],
  resume: [
    {
      id: 1,
      type: 'experience',
      title: 'Senior Frontend Developer',
      organization: 'Tech Company',
      location: 'Remote',
      start_date: '2023-01',
      end_date: null,
      description: 'Leading frontend development for enterprise applications.',
      skills: ['React', 'TypeScript', 'GraphQL']
    },
    {
      id: 2,
      type: 'experience',
      title: 'Full Stack Developer',
      organization: 'Startup Inc',
      location: 'Kuala Lumpur',
      start_date: '2021-06',
      end_date: '2022-12',
      description: 'Built and maintained web applications from scratch.',
      skills: ['Node.js', 'React', 'MongoDB']
    },
    {
      id: 3,
      type: 'education',
      title: 'Bachelor in Computer Science',
      organization: 'University',
      location: 'Malaysia',
      start_date: '2017-09',
      end_date: '2021-05',
      description: 'Graduated with honors. Focus on software engineering.',
      skills: ['Algorithms', 'Data Structures', 'Web Development']
    }
  ],
  links: [
    { id: 1, title: 'GitHub', url: 'https://github.com', icon: 'github', color: '#333' },
    { id: 2, title: 'LinkedIn', url: 'https://linkedin.com', icon: 'linkedin', color: '#0077b5' },
    { id: 3, title: 'Twitter', url: 'https://twitter.com', icon: 'twitter', color: '#1da1f2' },
    { id: 4, title: 'Portfolio', url: 'https://example.com', icon: 'globe', color: '#ff6b4a' }
  ]
};

function App() {
  const [profile, setProfile] = useState(null);
  const [projects, setProjects] = useState([]);
  const [resume, setResume] = useState([]);
  const [links, setLinks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [usingFallback, setUsingFallback] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      try {
        // Try fetching from Supabase
        const [profileData, projectsData, resumeData, linksData] = await Promise.all([
          fetchProfile(),
          fetchProjects(),
          fetchResume(),
          fetchLinks()
        ]);

        // Check if we got data, otherwise use fallback
        if (profileData) {
          setProfile(profileData);
          setProjects(projectsData || []);
          setResume(resumeData || []);
          setLinks(linksData || []);
        } else {
          // Use fallback data
          setProfile(fallbackData.profile);
          setProjects(fallbackData.projects);
          setResume(fallbackData.resume);
          setLinks(fallbackData.links);
          setUsingFallback(true);
        }
      } catch (error) {
        console.log('Using fallback data:', error);
        setProfile(fallbackData.profile);
        setProjects(fallbackData.projects);
        setResume(fallbackData.resume);
        setLinks(fallbackData.links);
        setUsingFallback(true);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, []);

  if (loading) {
    return (
      <div className="loading" style={{ minHeight: '100vh' }}>
        <div className="loading-spinner"></div>
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.5 }}
    >
      <Navbar />

      {usingFallback && (
        <div style={{
          background: 'var(--accent)',
          color: 'white',
          padding: '0.5rem',
          textAlign: 'center',
          fontSize: '0.85rem',
          fontFamily: 'JetBrains Mono, monospace'
        }}>
          ⚡ Demo Mode - Connect Supabase to load your real data
        </div>
      )}

      <main>
        <Hero profile={profile} />
        <Resume resume={resume} />
        <Projects projects={projects} />
        <Links links={links} />
      </main>

      <Footer profile={profile} />
    </motion.div>
  );
}

export default App;
